WITH unpacked AS (SELECT id, host, log_ts, latency_ms, status_code, context['region'] AS region, SIZE(context) AS num_context, SHIFTRIGHT(status_code, 2) AS status_code_high, COALESCE(context['region'], 'none') AS region_or_default, GET_JSON_OBJECT(payload_json, '$.duration') AS duration_text FROM app_logs WHERE latency_ms BETWEEN 652 AND 1938) SELECT id, log_ts, latency_ms, status_code, region, num_context, region_or_default, duration_text, MIN(status_code_high) OVER w_grp AS running_min_status_code_high, AVG(status_code_high) OVER w_grp AS running_avg_status_code_high, COUNT(status_code_high) OVER w_grp AS running_count_status_code_high, SUM(status_code_high) OVER w_grp AS running_sum_status_code_high FROM unpacked WINDOW w_grp AS (PARTITION BY host ORDER BY status_code ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)
